import time
from uuid import UUID, uuid4

from mc_shared import SlotOut

EVA = UUID(int=1)
ROBOTICS = UUID(int=2)
PILOTING = UUID(int=3)
GEOLOGY = UUID(int=4)
NAMES = {EVA: "EVA", ROBOTICS: "Robotics", PILOTING: "Piloting", GEOLOGY: "Geology"}


def slot(skill, level, position=1):
    return SlotOut(
        id=uuid4(), position=position, skill_id=skill, skill_name=NAMES[skill], min_level=level
    )


def crew(name, skills, workload_days=0):
    from mc_api.matcher import Candidate

    return Candidate(uuid4(), name, {k: v for k, v in skills.items()}, workload_days)


def holders_of(candidates):
    out = {}
    for c in candidates:
        for skill in c.skills:
            out[skill] = out.get(skill, 0) + 1
    return out


def run(slots, candidates):
    from mc_api.matcher import assign

    return assign(slots, candidates, holders_of(candidates))


def names(result):
    return [c.username if c else None for c in result]
import re
import uuid

from typer.testing import CliRunner

from mc_cli.commands import missions
from mc_cli.main import app
from mc_shared import SlotOut


def slot(position, skill, level):
    return SlotOut(
        id=uuid.uuid4(), position=position, skill_id=uuid.uuid4(), skill_name=skill, min_level=level
    )


def test_match_prints_the_table_and_the_summary(monkeypatch):
    from mc_shared import CrewSuggestion, MatchPreview, SlotMatch

    mission_id = uuid.uuid4()
    ben = CrewSuggestion(
        user_id=uuid.uuid4(), username="ben", display_name="Ben", level=3, workload_days=0
    )
    preview = MatchPreview(
        mission_id=mission_id,
        slots=[
            SlotMatch(slot=slot(1, "Piloting", 3), suggestion=ben),
            SlotMatch(slot=slot(2, "Medicine", 2), suggestion=None),
        ],
    )

    class Resp:
        def json(self):
            return preview.model_dump(mode="json")

    monkeypatch.setattr(missions, "request", lambda *a, **k: Resp())
    result = CliRunner().invoke(app, ["missions", "match", str(mission_id)])
    assert result.exit_code == 0, repr(result.exception)
    lines = result.output.splitlines()
    filled = next(line for line in lines if "Piloting" in line)
    assert re.search(r"\b1\b.*Piloting.*\b3\b.*ben.*\b3\b.*\b0\b", filled)
    empty = next(line for line in lines if "Medicine" in line)
    assert "2" in empty and "No match" in empty
    assert lines[-1].strip() == "1 of 2 slots filled"
import logging
from typing import TypeVar
from uuid import UUID

from fastapi import HTTPException
from sqlalchemy import Select, select
from sqlalchemy.orm import Session

from mc_api.models import Organization

T = TypeVar("T")
logger = logging.getLogger(__name__)


class OrgScope:
    """The only way for a route to read tenant data. Each query is limited to one org."""

    def __init__(self, session: Session, org_id: UUID) -> None:
        self.session = session
        self.org_id = org_id

    def select(self, model: type[T]) -> Select[tuple[T]]:
        return select(model).where(model.org_id == self.org_id)

    def get(self, model: type[T], id: UUID, *, for_update: bool = False) -> T:
        # Not session.get: it has no org filter. A missing row and another org give the same 404.
        query = self.select(model).where(model.id == id)
        row = self.session.scalar(query.with_for_update() if for_update else query)
        if row is None:
            # One message for a missing row and a row of another org, like the 404 body.
            logger.info("not found: %s %s in org %s", model.__name__, id, self.org_id)
            raise HTTPException(404, "Not found")
        return row

    def org(self) -> Organization:
        return self.session.scalars(
            select(Organization).where(Organization.id == self.org_id)
        ).one()

